#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 2005
#define INF 1000000000

int n;
int s[MAXN];
int dp[MAXN][MAXN]; // dp[i][j] = max score starting from i with last move length j (for A=j or B=j)

int main() {
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &s[i]);
    }

    // Initialize dp with -INF
    for (int i = 0; i < n; i++) {
        for (int j = 0; j <= n; j++) {
            dp[i][j] = -INF;
        }
    }

    // Base case: starting at 0, we haven't made any move yet
    // We treat starting score as s[0] (we collect the lotus at start)
    // For the first move, any A or B is possible, but we need to track the length.
    // We'll handle first move separately.

    int ans = s[0]; // At least we can collect the starting lotus

    // For each possible first move length L (1 to n-1)
    for (int L = 1; L < n; L++) {
        // Move forward by L (A = L)
        if (L < n) {
            dp[L][L] = s[0] + s[L];
            if (dp[L][L] > ans) ans = dp[L][L];
        }
        // Move backward: but we start at 0, so x - B < 0 would drown. So no backward first move.
    }

    // Now DP for other positions
    // For each position i from 1 to n-1
    for (int i = 1; i < n; i++) {
        for (int L = 1; L <= i; L++) { // last move length L
            if (dp[i][L] == -INF) continue;
            // From i with last move length L, we can:
            // 1. Move forward by L (A = L) to i+L, if within bounds
            if (i + L < n) {
                int ni = i + L;
                if (dp[i][L] + s[ni] > dp[ni][L]) {
                    dp[ni][L] = dp[i][L] + s[ni];
                    if (dp[ni][L] > ans) ans = dp[ni][L];
                }
            }
            // 2. Move backward by L (B = L) to i-L, if within bounds
            if (i - L >= 0) {
                int ni = i - L;
                if (dp[i][L] + s[ni] > dp[ni][L]) {
                    dp[ni][L] = dp[i][L] + s[ni];
                    if (dp[ni][L] > ans) ans = dp[ni][L];
                }
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

