typedef long long ll;

static ll gcdll(ll a, ll b) {
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *s = (ll *)malloc((size_t)N * sizeof(ll));
    for (int i = 0; i < N; ++i) scanf("%lld", &s[i]);

    if (N == 1) {
        printf("%lld\n", s[0]);
        free(s);
        return 0;
    }

    ll ans = s[0];

    for (int d = 1; d < N; ++d) {
        ll g = gcdll((ll)N, (ll)d);
        ll cycle_sum = 0;

        for (int start = 0; start < g; ++start) {
            ll cur = 0, best = 0;
            for (int x = start; x < N; x += g) {
                cur += s[x];
                if (cur < 0) cur = 0;
                if (cur > best) best = cur;
            }
            cycle_sum += best;
        }

        if (cycle_sum > ans) ans = cycle_sum;
    }

    printf("%lld\n", ans);
    free(s);
    return 0;
}

