import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        long[] s = new long[N];
        for (int i = 0; i < N; i++) s[i] = fs.nextLong();

        // Let g = gcd(A, B). Reachable positions from 0 are exactly multiples of g.
        // To never drown, every visited position must lie in [0, N-1], so all reachable
        // multiples of g inside this interval are safe, and any move from one such point
        // to another is possible iff A/g and B/g are coprime. For any chosen g, we can
        // choose A=g, B=g, so all multiples of g are reachable. Thus score for g is
        // sum of s[i] over i divisible by g. Answer is max over g >= 1.
        //
        // Since positions are 0..N-1, and 0 is divisible by every g, score(g) =
        // s[0] + sum_{k>=1, k*g < N} s[k*g].

        long ans = Long.MIN_VALUE;
        for (int g = 1; g < N; g++) {
            long sum = 0;
            for (int x = 0; x < N; x += g) sum += s[x];
            if (sum > ans) ans = sum;
        }
        // Also possible to choose g >= N, then only position 0 is reachable.
        ans = Math.max(ans, s[0]);

        System.out.println(ans);
    }
}
